import { readdirSync, readFileSync } from "node:fs";

export const literalPattern =
  /#[\da-f]{8}\b|#[\da-f]{6}\b|#[\da-f]{4}\b|#[\da-f]{3}\b|(?<![a-z])(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch|color)\(|\b(?:bg|text|border|ring|outline|fill|stroke|shadow|from|via|to|accent|decoration|divide|placeholder)-(?:white|black|(?:slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-\d{2,3})(?:\/\d+)?\b|(?:\b(?:color|background|border-color|fill|stroke|stop-color)\s*[:=]\s*["']?)(?:white|black|blue|red|green|yellow|gray|grey|purple|pink|orange|rebeccapurple)\b/gi;
const namedColor =
  /(?<![-\w])(?:aliceblue|antiquewhite|aqua|aquamarine|azure|beige|bisque|black|blanchedalmond|blue|blueviolet|brown|burlywood|cadetblue|chartreuse|chocolate|coral|cornflowerblue|cornsilk|crimson|cyan|darkblue|darkcyan|darkgoldenrod|darkgray|darkgreen|darkgrey|darkkhaki|darkmagenta|darkolivegreen|darkorange|darkorchid|darkred|darksalmon|darkseagreen|darkslateblue|darkslategray|darkslategrey|darkturquoise|darkviolet|deeppink|deepskyblue|dimgray|dimgrey|dodgerblue|firebrick|floralwhite|forestgreen|fuchsia|gainsboro|ghostwhite|gold|goldenrod|gray|green|greenyellow|grey|honeydew|hotpink|indianred|indigo|ivory|khaki|lavender|lavenderblush|lawngreen|lemonchiffon|lightblue|lightcoral|lightcyan|lightgoldenrodyellow|lightgray|lightgreen|lightgrey|lightpink|lightsalmon|lightseagreen|lightskyblue|lightslategray|lightslategrey|lightsteelblue|lightyellow|lime|limegreen|linen|magenta|maroon|mediumaquamarine|mediumblue|mediumorchid|mediumpurple|mediumseagreen|mediumslateblue|mediumspringgreen|mediumturquoise|mediumvioletred|midnightblue|mintcream|mistyrose|moccasin|navajowhite|navy|oldlace|olive|olivedrab|orange|orangered|orchid|palegoldenrod|palegreen|paleturquoise|palevioletred|papayawhip|peachpuff|peru|pink|plum|powderblue|purple|rebeccapurple|red|rosybrown|royalblue|saddlebrown|salmon|sandybrown|seagreen|seashell|sienna|silver|skyblue|slateblue|slategray|slategrey|snow|springgreen|steelblue|tan|teal|thistle|tomato|turquoise|violet|wheat|white|whitesmoke|yellow|yellowgreen)(?![-\w])/gi;
export function findColorLiterals(source: string) {
  const clean = source.replace(/\/\*[\s\S]*?\*\//g, "");
  const found = [...clean.matchAll(literalPattern)].map((m) => m[0]);
  // Include function arguments and arbitrary named colors, excluding variable names.
  const values = [
    ...clean.matchAll(
      /(?:--[\w-]+|color|background(?:Color|-color)?|border(?:Color|-color)?|outline(?:Color|-color)?|fill|stroke|stopColor|stop-color|boxShadow|box-shadow)\s*[:=]\s*["'`]?([^;{}"'`\n]+)/g,
    ),
  ];
  for (const value of values)
    for (const color of value[1].matchAll(namedColor)) {
      if (!found.some((item) => item.endsWith(color[0]) && /[:=]/.test(item)))
        found.push(color[0]);
    }
  for (const utility of clean.matchAll(
    /(?:bg|text|border|ring|outline|fill|stroke|shadow|from|via|to|accent|decoration|placeholder)-\[([^\]]+)\]/g,
  )) {
    for (const color of utility[1].matchAll(namedColor)) found.push(color[0]);
  }
  return found;
}
function files(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = `${dir}/${entry.name}`;
    if (entry.name === "generated") return [];
    return entry.isDirectory()
      ? files(path)
      : /\.(?:[cm]?[jt]sx?|css|svg|html)$/.test(path)
        ? [path]
        : [];
  });
}
export function checkColors() {
  const exceptions: Record<string, { reason: string; literals: string[] }> =
    JSON.parse(readFileSync("scripts/color-exceptions.json", "utf8"));
  const failures = [];
  for (const file of [...files("src"), ...files("public")]) {
    if (file === "src/app/theme-tokens.css") continue;
    const found = findColorLiterals(readFileSync(file, "utf8"));
    const allowed = exceptions[file]?.literals ?? [];
    if (JSON.stringify(found) !== JSON.stringify(allowed))
      failures.push({ file, found, allowed });
  }
  return failures;
}
if (process.argv[1]?.endsWith("check-colors.ts")) {
  const failures = checkColors();
  if (failures.length) {
    console.error(JSON.stringify(failures, null, 2));
    process.exitCode = 1;
  } else console.log("Application color literal check passed.");
}
